const envelope = $input.first().json || {};
const payload = typeof envelope.body === 'string' ? JSON.parse(envelope.body) : (envelope.body || envelope);
const required = ['asset_id', 'title', 'caption', 'source_media_url', 'start_seconds', 'end_seconds', 'channel'];
const missing = required.filter((key) => payload[key] === undefined || payload[key] === null || payload[key] === '');
const channels = ['instagram', 'facebook', 'linkedin', 'tiktok', 'youtube'];
if (missing.length) throw new Error(`Invalid video publish payload. Missing: ${missing.join(', ')}`);
if (!channels.includes(String(payload.channel).toLowerCase())) throw new Error('Unsupported publishing channel');
if (Number(payload.start_seconds) < 0 || Number(payload.end_seconds) <= Number(payload.start_seconds)) throw new Error('Invalid clip timestamps');
if (!String(payload.source_media_url).startsWith('https://')) throw new Error('Video media URL must be HTTPS');
return [{ json: { ...payload, channel: String(payload.channel).toLowerCase(), requested_at: new Date().toISOString() } }];

const result = $input.first().json || {};
const published = result.published === true || result.status === 'published';
if (!published) throw new Error(result.message || result.error || 'Channel adapter did not confirm publication');
return [{ json: { status: 'success', published: true, asset_id: $('Validate Approved Clip').first().json.asset_id, channel: $('Validate Approved Clip').first().json.channel, url: result.url || result.permalink || null, provider: result.provider || 'configured_channel_adapter', published_at: result.published_at || new Date().toISOString() } }];
